package beer

import "testing"

func TestEdges(t *testing.T) {
	for _, n := range []int{-1, 100, 1000} {
		if s, err := Verse(n); err == nil {
			t.Fatalf("Verse(%d): expected error, got %q", n, s)
		}
	}
	for _, tc := range [][2]int{{0, 1}, {8, 8}, {99, 99}, {0, 0}, {100, 0}, {-5, 0}, {0, -1}} {
		s, err := Verses(tc[0], tc[1])
		wantErr := tc[0] > 99 || tc[1] < 0 || tc[0] < tc[1]
		if wantErr && err == nil {
			t.Fatalf("Verses(%d,%d): expected error, got %q", tc[0], tc[1], s)
		}
		if !wantErr && err != nil {
			t.Fatalf("Verses(%d,%d): unexpected error %v", tc[0], tc[1], err)
		}
	}

	if got, _ := Verse(99); got != "99 bottles of beer on the wall, 99 bottles of beer.\nTake one down and pass it around, 98 bottles of beer on the wall.\n" {
		t.Fatalf("Verse(99) wrong: %q", got)
	}
	if got, _ := Verses(2, 2); got != "2 bottles of beer on the wall, 2 bottles of beer.\nTake one down and pass it around, 1 bottle of beer on the wall.\n\n" {
		t.Fatalf("Verses(2,2) wrong: %q", got)
	}
	if got, _ := Verses(0, 0); got != "No more bottles of beer on the wall, no more bottles of beer.\nGo to the store and buy some more, 99 bottles of beer on the wall.\n\n" {
		t.Fatalf("Verses(0,0) wrong: %q", got)
	}
	if song := Song(); len(song) == 0 || song[len(song)-2:] != "\n\n" {
		t.Fatalf("Song() does not end with a blank line as Verses(99,0) does")
	}
}
